import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    weekday_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}

    if freq == "WEEKLY":
        target_days = sorted(weekday_map[d] for d in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(result) < count:
            monday = week0_monday + timedelta(days=7 * w)
            for wd in target_days:
                candidate = monday + timedelta(days=wd)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        break
            w += k
        return result

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        m = 0
        if len(parts) == 3:
            d = int(parts[2])
            while len(result) < count:
                year, month_idx = divmod(base_months + m, 12)
                month = month_idx + 1
                num_days = calendar.monthrange(year, month)[1]
                day = num_days if d == -1 else d
                if day <= num_days:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                m += k
        else:
            n = int(parts[2])
            wd = weekday_map[parts[3]]
            while len(result) < count:
                year, month_idx = divmod(base_months + m, 12)
                month = month_idx + 1
                first_wd, num_days = calendar.monthrange(year, month)
                if n > 0:
                    day = 1 + (wd - first_wd) % 7 + 7 * (n - 1)
                else:
                    last_wd = (first_wd + num_days - 1) % 7
                    day = num_days - ((last_wd - wd) % 7)
                if day <= num_days:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                m += k
        return result

    if freq == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        y = 0
        while len(result) < count:
            year = start_date.year + y
            try:
                candidate = date(year, mm, dd)
            except ValueError:
                y += k
                continue
            if candidate >= start_date:
                result.append(candidate.isoformat())
            y += k
        return result

    raise ValueError(f"Unsupported rule: {rule}")
